function businessAgentCapabilities(){return {reads:['search and analysis of the synced copy of every company record (queryCompanyData, no QuickBooks requests)','company records','linked transaction chains','financial reports','receivables and payables obligations'],activityPolicy:require('./business-activity-batch').POLICY,activityPolicyHash:require('./business-activity-batch').POLICY_HASH,actions:['run sales and purchases over time: invoice published services and record operating bills on payment terms (left open), then collect or pay its own open terms invoices and bills in full or in part on later days; send field-service estimates and later convert them into time and an invoice on terms; raise stock purchase orders that are received later','correct its own earlier records by reversing them today (never editing or voiding the original): a full credit applied to a wholly unpaid service invoice, a refund of a fully collected service sale, a full supplier credit applied to a wholly unpaid operating bill, or the exact reverse of its journal entry, each at the original tax rate and at most once per record','add new customers, suppliers and service items (names unused in QuickBooks, no opening balances); each is usable in a later batch after it verified: added customers and items in service sales, added suppliers in paid bills','receive wholly unreceived managed or adopted purchase orders in full into unpaid inventory bills today, at original PO cost with purchase tax and exact FIFO stock evidence (partial receipts unavailable)','prepare and execute additional same-day settled service sales and paid non-stock overhead','record operating expenses paid directly from the operating bank and supplier credits that reduce accounts payable (operating-expense account with purchase tax, up to $10,000 before tax each)','record open customer credit memos and customer refunds paid from the operating bank for published services (sales tax; up to 8 units at $1,000 each)','transfer between two published bank accounts (up to $50,000; unavailable while only one bank account is published)','post balanced journal entries of two to four lines on published income and operating-expense accounts with no bank line (up to $10,000 per line; never receivables, payables, undeposited funds or stock)','collect open invoices and pay open bills from the adopted import history: customer payments deposited to the operating bank, and supplier payments from the operating bank (up to $50,000 each and $120,000 per batch, never more than the open balance)','prepare and execute exact published-policy business periods','retain decisions and operating memory','link existing troubleshooting cases'],specialists:['receivables','payables','inventory'],boundaries:['Calendar activity uses saved dated rules. Additional activity uses a separately granted policy and leaves verified history unchanged; no lifetime activity quota applies.','Settlements apply only to invoices and bills saved and verified by the adopted import, re-read from QuickBooks before saving; records entered outside the app are never paid or collected.','Protected dates, original-record ownership and uncertain-write recovery remain enforced.','Troubleshooting cases are distinct scoped workflows; linking a case does not run it.']};}
